/*
 * Client-side mirror of `isValidHandle` from @medusajs/framework/utils.
 *
 * The rule MUST match the server's, because a seller who leaves the handle
 * blank gets one generated by `toHandle(name)` — which deliberately preserves
 * letters from any script, so a Persian store name yields a Persian handle.
 * An ASCII-only client rule then rejects the store's own saved handle and
 * makes the whole edit form unsubmittable.
 */

const HANDLE_PATTERN = /^[\p{Ll}\p{Lo}\p{Lm}\p{N}]+(?:-[\p{Ll}\p{Lo}\p{Lm}\p{N}]+)*$/u

export const isValidHandle = (value: string): boolean => {
  if (!value?.length) {
    return false
  }
  // Uppercase ASCII is rejected server-side to keep handles consistent with the
  // always-lowercase generated ones and avoid case-duplicate index collisions.
  if (/[A-Z]/.test(value)) {
    return false
  }
  return HANDLE_PATTERN.test(value)
}

/*
 * A NEW product's handle is Latin only: lowercase a-z, digits and single
 * hyphens, 3 to 60 characters (owner decisions 165, 196). The backend
 * (dfactories-mp `lib/product-handle.ts`) is the authority and also refuses a
 * reserved word; this mirror only gives the producer an inline error early.
 * Store handles keep `isValidHandle` above, which accepts Persian.
 */
const LATIN_PRODUCT_HANDLE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

export const isValidLatinProductHandle = (value: string): boolean =>
  value.length >= 3 && value.length <= 60 && LATIN_PRODUCT_HANDLE.test(value)
